<?= $this->extend('admin/layouts/main') ?><?= $this->section('content') ?><div class="d-flex justify-content-between mb-4"><h1 class="h3">Packages</h1><a class="btn btn-success" href="<?= url_to('admin.packages.create') ?>">Add Package</a></div><form class="card border-0 p-3 mb-3" method="get"><div class="row g-2"><div class="col-md-8"><input class="form-control" name="q" value="<?= esc($q) ?>" placeholder="Name or package code"></div><div class="col-md-3"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['draft','active','inactive'] as $s): ?><option value="<?= $s ?>" <?= $status===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach ?></select></div><div class="col-md-1"><button class="btn btn-success w-100">Go</button></div></div></form><div class="card border-0"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Image</th><th>Code / Name</th><th>Regular Total</th><th>Package Price</th><th>Savings</th><th>Available</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($packages as $p): ?><tr><td><?php if($p['main_image']): ?><img src="<?= base_url($p['main_image']) ?>" width="48" height="48" class="rounded object-fit-cover" alt=""><?php else: ?>—<?php endif ?></td><td><small><?= esc($p['package_code']) ?></small><br><strong><?= esc($p['name']) ?></strong></td><td>৳<?= number_format((float)$p['regular_total'],2) ?></td><td>৳<?= number_format((float)$p['package_price'],2) ?></td><td>৳<?= number_format(max(0,(float)$p['regular_total']-(float)$p['package_price']),2) ?></td><td><?= $p['available']>=999999?'Unlimited':$p['available'] ?></td><td><?= esc($p['status']) ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= url_to('admin.packages.edit',$p['id']) ?>">Edit</a> <form class="d-inline" method="post" action="<?= site_url('admin/packages/'.$p['id'].'/delete') ?>" onsubmit="return confirm('Delete this package?')"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach ?><?php if(!$packages): ?><tr><td colspan="8" class="text-center text-muted py-4">No packages found.</td></tr><?php endif ?></tbody></table></div></div><div class="mt-3"><?= $pager->links() ?></div><?= $this->endSection() ?>
